import java.math.BigDecimal;
import java.time.Instant;

/**
 * 不确定度分量。一条测量（具体版本行）可登记多个非负分量，名称在同一测量同一预算版本内唯一。
 *
 * @param id            分量 ID（自增）
 * @param measurementId 所属测量记录（版本行）ID
 * @param budgetVersion 预算版本号，从 1 开始；整体替换递增，历史版本只增不改
 * @param name          分量名称，非空；同一测量同一预算版本内唯一
 * @param magnitude     分量大小，非负（含 0），最多 6 位小数
 * @param createdAt     该预算版本写入时间（UTC）
 */
public record UncertaintyComponent(
        long id,
        long measurementId,
        int budgetVersion,
        String name,
        BigDecimal magnitude,
        Instant createdAt) {
}

package com.example.starter.calibration.model;

import java.time.Instant;

/**
 * 幂等请求记录。仅成功结论占键；指纹由操作者、操作类型、规范化参数集合及所有影响结果字段构造。
 *
 * @param requestId   客户端幂等键（X-Request-Id）
 * @param operation   操作类型：UPDATE_BUDGET/REVISE_MEASUREMENT/RELEASE_BUDGET/REVOKE_CERTIFICATE
 * @param fingerprint 规范化请求指纹（SHA-256 十六进制）
 * @param responseJson 首次成功的完整响应 JSON 快照
 * @param createdAt   首次成功时间（UTC）
 */
public record IdempotentRequest(
        String requestId,
        String operation,
        String fingerprint,
        String responseJson,
        Instant createdAt) {
}

