                            + "threshold_id, threshold_version, threshold_value, uncertainty_ok, decision, "
                            + "released_by, released_at) "
                            + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, snapshot.batchId());
            ps.setLong(2, snapshot.measurementId());
