package com.example.starter.calibration.service;

import java.util.Map;
import java.util.function.Supplier;

import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import com.example.starter.calibration.api.ApiException;
import com.example.starter.calibration.model.IdempotentRequest;
import com.example.starter.calibration.repo.IdempotentRequestRepository;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;

/**
 * 幂等执行器：同一 requestId 的请求按规范化指纹裁决——
 * 同参重放返回首次成功的完整响应快照（读取不改状态），异参返回 409，失败不占键。
 *
 * <p>业务动作与占键记录在同一事务内：动作抛异常则整体回滚，不写幂等记录；
 * 仅动作成功后才占键。并发同键由主键冲突兜底，冲突后重读首次记录裁决。
 */
@Service
public class IdempotencyService {

    private final IdempotentRequestRepository requests;
    private final ObjectMapper objectMapper;
    private final BusinessClock clock;

    public IdempotencyService(IdempotentRequestRepository requests,
                              ObjectMapper objectMapper,
                              BusinessClock clock) {
        this.requests = requests;
        this.objectMapper = objectMapper;
        this.clock = clock;
    }

    /**
     * 幂等执行结果。
     *
     * @param replay    是否为重放（true 时 body 为首次响应反序列化对象）
     * @param body      响应体对象（首次成功结果或重放反序列化结果）
     * @param replayJson 重放时的首次原始响应 JSON；首次执行为 null
     */
    public record Result<T>(boolean replay, T body, String replayJson) {
    }

    /**
     * 无 requestId 时直接执行业务动作，不占键不查重。
     */
    public <T> Result<T> executeWithoutIdempotency(Supplier<T> action) {
        return new Result<>(false, action.get(), null);
    }

    /**
     * 带 requestId 的幂等执行。
     *
     * @param requestId 客户端幂等键（已校验非空）
     * @param operation 操作类型
     * @param actor     操作者（纳入指纹）
     * @param fields    规范化参数集合及所有影响结果字段（纳入指纹）
     * @param action    业务动作（与占键同事务）
     * @param type      响应类型，用于重放反序列化
     */
    @Transactional
    public <T> Result<T> execute(String requestId, String operation, String actor,
                                 Map<String, ?> fields, Supplier<T> action, Class<T> type) {
        String fingerprint = Fingerprints.of(actor, operation, fields);

        var existing = requests.findById(requestId);
        if (existing.isPresent()) {
            return replay(existing.get(), operation, fingerprint, type);
        }

        T result;
        try {
            result = action.get();
        } catch (RuntimeException ex) {
            // 业务失败：不占键，异常向上抛出由全局处理映射状态码，事务回滚
            throw ex;
        }
        String json = toJson(result);
        try {
            requests.insert(new IdempotentRequest(requestId, operation, fingerprint, json, clock.now()));
        } catch (DuplicateKeyException concurrent) {
            // 并发同键：另一事务已提交占键，重读裁决
            IdempotentRequest winner = requests.findById(requestId)
                    .orElseThrow(() -> ApiException.conflict("IDEMPOTENCY_RACE", "幂等键并发冲突: " + requestId));
            return replay(winner, operation, fingerprint, type);
        }
        return new Result<>(false, result, null);
    }

    private <T> Result<T> replay(IdempotentRequest recorded, String operation,
                                 String fingerprint, Class<T> type) {
        if (!recorded.operation().equals(operation) || !recorded.fingerprint().equals(fingerprint)) {
            throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
                    "requestId 已用于不同参数或操作的请求: " + recorded.requestId());
        }
        try {
            return new Result<>(true, objectMapper.readValue(recorded.responseJson(), type),
                    recorded.responseJson());
        } catch (JsonProcessingException ex) {
            throw new IllegalStateException("首次响应快照无法反序列化", ex);
        }
    }

    private String toJson(Object result) {
        try {
            return objectMapper.writeValueAsString(result);
        } catch (JsonProcessingException ex) {
            throw new IllegalStateException("响应快照序列化失败", ex);
        }
    }
}

