package com.example.starter.calibration.repo;

import java.time.LocalDateTime;
import java.util.Optional;

import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import com.example.starter.calibration.model.IdempotentRequest;

/**
 * 幂等请求持久化。仅成功结论占键；同 requestId 同参重放返回首次响应快照，异参由服务层判 409。
 */
@Repository
public class IdempotentRequestRepository {

    private final JdbcTemplate jdbc;

    public IdempotentRequestRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 按 requestId 查询已占键记录（不加锁）。
     */
    public Optional<IdempotentRequest> findById(String requestId) {
        return jdbc.query(
                        "SELECT * FROM idempotent_request WHERE request_id = ?",
                        (rs, n) -> new IdempotentRequest(
                                rs.getString("request_id"),
                                rs.getString("operation"),
                                rs.getString("fingerprint"),
                                rs.getString("response_json"),
                                JdbcTimes.fromDb(rs.getObject("created_at", LocalDateTime.class))),
                        requestId)
                .stream().findFirst();
    }

    /**
     * 按 requestId 查询并加行锁（须在事务内调用），串行化同键并发请求。
     */
    public Optional<IdempotentRequest> findByIdForUpdate(String requestId) {
        return jdbc.query(
                        "SELECT * FROM idempotent_request WHERE request_id = ? FOR UPDATE",
                        (rs, n) -> new IdempotentRequest(
                                rs.getString("request_id"),
                                rs.getString("operation"),
                                rs.getString("fingerprint"),
                                rs.getString("response_json"),
                                JdbcTimes.fromDb(rs.getObject("created_at", LocalDateTime.class))),
                        requestId)
                .stream().findFirst();
    }

    /**
     * 占键并保存首次成功响应；requestId 冲突抛 DuplicateKeyException（并发同键）。
     */
    public void insert(IdempotentRequest request) {
        jdbc.update("INSERT INTO idempotent_request "
                        + "(request_id, operation, fingerprint, response_json, created_at) "
                        + "VALUES (?, ?, ?, ?, ?)",
                request.requestId(), request.operation(), request.fingerprint(),
                request.responseJson(), JdbcTimes.toDb(request.createdAt()));
    }

    /**
     * 唯一约束冲突判定。
     */
    public static boolean isDuplicate(DuplicateKeyException ex) {
        return ex instanceof DuplicateKeyException;
    }
}

