    }

    public BatchRejectedException(HttpStatus status, String code, String message, List<ItemFailure> failures) {
        super(status, code, message);
        this.failures = List.copyOf(failures);
    }

    public List<ItemFailure> getFailures() {
        return failures;
    }
}

