                                {"instrumentId":"INS-G","validFrom":"2028-01-01T00:00:00Z","threshold":"-1"}"""))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.code").value("INVALID_THRESHOLD"));
    }
