                        .header("X-Actor-Id", "carol").header("X-Request-Id", "REQ-R")
                        .contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.snapshots[0].thresholdVersion").value(1));
