        mvc.perform(get("/api/diagnostics/snapshots")
                        .param("from", "2026-06-01T12:00:00Z")
                        .param("to", "2026-06-01T12:00:01Z"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1));
